Lemma blk63 m b : x_pend X = None -> In (m, b) (gmetas st) -> m_sizeclass (MR st m) = 63 ->
  In (blk_of (m, b)) BL /\ bslot (blk_of (m, b)) = slot_start' (MR st m) 0 /\ isbig (blk_of (m, b)) = true
